package com.healthcare.portal.controller;
import com.healthcare.portal.entity.Payment; import com.healthcare.portal.repository.PaymentRepository; import com.healthcare.portal.service.PdfInvoiceService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/invoices") public class InvoiceController { private final PaymentRepository payments; private final PdfInvoiceService pdf; public InvoiceController(PaymentRepository p,PdfInvoiceService s){payments=p;pdf=s;} @GetMapping("/{orderId}") public ResponseEntity<byte[]> invoice(@PathVariable String orderId){Payment p=payments.findByRazorpayOrderId(orderId).orElseThrow(); return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=invoice-"+orderId+".pdf").body(pdf.invoice(p));} }
